import NetInfo, { type NetInfoState } from '@react-native-community/netinfo'
import { useEffect, useRef, useState } from 'react'
import { toast } from '../toast'
import { Wifi, WifiOff } from 'lucide-react-native'
import { NativeModules } from 'react-native'
const netInfoAvailable = !!NativeModules.RNCNetInfo

export const useOnlineStatus = (gracePeriodInMs: number = 1000) => {
	const [isOnline, setIsOnline] = useState<boolean | null>(null)
	const timeoutRef = useRef<NodeJS.Timeout | null>(null)
	const toastIdRef = useRef<string | number | null>(null)
	const showedOnlineToastRef = useRef<boolean>(true) // initially true so we dont show toast when hook is mounted

	const clearToast = () => {
		if (toastIdRef.current) toast.hide(toastIdRef.current)
		toastIdRef.current = null
	}

	useEffect(() => {
		if (netInfoAvailable) {
			const unsubscribe = NetInfo.addEventListener((state: NetInfoState) => {
				const reachable =
					!!state.isConnected && state.isInternetReachable !== false

				// network is back online
				if (reachable) {
					if (!showedOnlineToastRef.current) {
						toast.show({
							message: 'Back online',
							variant: 'success',
							customIcon: Wifi
						})
						showedOnlineToastRef.current = true
					}
					if (timeoutRef.current) clearTimeout(timeoutRef.current)
					clearToast()
					setIsOnline(true)
					return
				}

				// network is offline
				if (timeoutRef.current) clearTimeout(timeoutRef.current)
				timeoutRef.current = setTimeout(() => {
					toastIdRef.current = toast.show({
						message: 'No internet connection',
						variant: 'error',
						duration: Infinity,
						customIcon: WifiOff
					})
					showedOnlineToastRef.current = false
					setIsOnline(false)
				}, gracePeriodInMs)
			})

			return () => {
				unsubscribe()
				if (timeoutRef.current) clearTimeout(timeoutRef.current)
				clearToast()
			}
		}
		return
	}, [gracePeriodInMs])

	return isOnline
}
